phr=sorted({x for line in P.split('\n') for x in line.split('|') if x},key=len,reverse=True)
found=set()
lead=re.compile(r'(?:^|; |\. )([A-Z][^:;.]{1,45}):')
def mark(t):
    spans=[]
    def free(a,b): return all(b<=x or a>=y for x,y in spans)
    for p in phr:
        i=t.find(p)
        while i!=-1:
            found.add(p)
            if free(i,i+len(p)): spans.append((i,i+len(p)))
            i=t.find(p,i+1)
    for m in lead.finditer(t):
        a,b=m.start(1),m.end(1)
        if free(a,b): spans.append((a,b))
    # split spans on '; ' so list items stay balanced
    out=[]
    for a,b in spans:
        seg=t[a:b];pos=a
        for part in seg.split('; '):
            out.append((pos,pos+len(part)));pos+=len(part)+2
    for a,b in sorted(out,reverse=True):
        t=t[:a]+'**'+t[a:b]+'**'+t[b:]
    return t
N=[[d[0]]+[mark(x) for x in d[1:]] for d in D]
missing=[p for p in phr if p not in found]
print('phrases',len(phr),'missing',len(missing));print(missing)
open('cards.js','w').write('window.DETAILS='+json.dumps(N,ensure_ascii=False,indent=0)+';\n')
